# Let me also check the pending exception and worker health details
snapshot = json.loads(json.dumps(snapshot))
workers = snapshot["workers"]

# Check for any workers with exceptions or non-ok status
print("=== WORKERS WITH ISSUES ===")
for w in workers:
    s = w["summary"]
    if s["last_status"] != "ok" or s["exceptions"] > 0 or s["all_time_exceptions"] > 0:
        print(f"  {w['name']}: last_status={s['last_status']}, exceptions={s['exceptions']}, all_time_exceptions={s['all_time_exceptions']}, investigation={s['investigation']}")

print("\n=== PENDING EXCEPTIONS ===")
for pe in snapshot.get("pending_exceptions", []):
    print(f"  {pe['worker']}: state={pe['state']}, failure={pe['failure']}")

# Check the reservation workers specifically
print("\n=== RESERVATION WORKERS ===")
for w in workers:
    if w["task"] == "reservation":
        s = w["summary"]
        print(f"  {w['name']}: customer={w['customer']}, committing={w['committing']}, effect={w['effect']}")
        print(f"    last_status={s['last_status']}, successes={s['successes']}, exceptions={s['exceptions']}, effects_failed={s['effects_failed']}")
        print(f"    rows_refused={s['rows_refused']}, effects_applied={s['effects_applied']}")
        # Check recent runs for details
        for r in w["recent_runs"]:
            if not r["ok"] or r.get("problems"):
                print(f"    PROBLEM RUN at {r['at']}: ok={r['ok']}, decision={r.get('decision')}, problems={r.get('problems')}, effect_applied={r.get('effect_applied')}")

# Check digest distribution among engine types
print("\n=== DIGEST x ENGINE CROSS-TAB ===")
from collections import defaultdict
cross = defaultdict(lambda: defaultdict(int))
for w in workers:
    cv = w["current_version"]
    digest = None
    for entry in w["version_history"]:
        if entry["version"] == cv:
            digest = entry["digest"]
            break
    cross[w["engine"]][digest] += 1

for engine, digests in cross.items():
    print(f"  {engine}:")
    for d, cnt in sorted(digests.items(), key=lambda x: -x[1]):
        print(f"    {d[:16]}...: {cnt}")
